import numpy as np, torch, model
net = model.load(); neg = model.negatives()
w = torch.tensor(np.load('contrast_c2_blocks.1_k8.npy')); b=-12.7885
torch.manual_seed(0); N=4096
xi = torch.randn(N,2); c = torch.rand(N)
st = {}
def hb(m,i,o): st['f'] = (o@w + b) > 0
h1 = net.blocks[1].register_forward_hook(hb)
def ho(m,i,o):
    if st.get('delta') is None or not (st['lo']<=st['k']<st['hi']): return o
    return o + st['f'].float()[:,None]*st['delta']
h2 = net.out.register_forward_hook(ho)
@torch.no_grad()
def run(delta=None, lo=0, hi=0):
    st['delta']=None if delta is None else torch.tensor(delta,dtype=torch.float32); st['lo'],st['hi']=lo,hi
    x=xi.clone(); fires=[]
    for k in range(20):
        st['k']=k; t=torch.full((N,),1-k/20)
        v,_=net.velocity(x,t,c,(),count=False); fires.append(st['f'].clone()); x=x-v/20
    return x, torch.stack(fires)
a0,F0=run()
lab = F0[8] # target proxy
print('label share',lab.float().mean().item(), 'fire share by step', F0.float().mean(1).numpy().round(3))
print('target action mean', a0[lab].mean(0).numpy(), 'other', a0[~lab].mean(0).numpy())
